<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>可衣 - 悦享都市时尚</title>
    <style>
        :root {
            --primary-color: #1a1a1a;
            --accent-color: #8c7b75;
            --bg-color: #ffffff;
            --light-bg: #f9f9f9;
            --text-color: #333333;
            --gray-text: #666666;
            --border-color: #e5e5e5;
            --container-width: 1200px;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif;
            color: var(--text-color);
            background-color: var(--bg-color);
            line-height: 1.6;
        }

        a {
            text-decoration: none;
            color: inherit;
            transition: color 0.3s;
        }

        ul {
            list-style: none;
        }

        img {
            max-width: 100%;
            display: block;
        }

        /* Layout Utilities */
        .container {
            max-width: var(--container-width);
            margin: 0 auto;
            padding: 0 20px;
        }

        .btn {
            display: inline-block;
            padding: 10px 24px;
            background-color: var(--primary-color);
            color: #fff;
            text-align: center;
            cursor: pointer;
            border: none;
            font-size: 14px;
            transition: background-color 0.3s;
        }

        .btn:hover {
            background-color: #000;
        }

        .btn-outline {
            background-color: transparent;
            border: 1px solid var(--primary-color);
            color: var(--primary-color);
        }

        .btn-outline:hover {
            background-color: var(--primary-color);
            color: #fff;
        }

        /* Header */
        header {
            border-bottom: 1px solid var(--border-color);
            position: sticky;
            top: 0;
            background: rgba(255, 255, 255, 0.95);
            z-index: 100;
        }

        .nav-wrapper {
            display: flex;
            justify-content: space-between;
            align-items: center;
            height: 80px;
        }

        .logo {
            font-size: 24px;
            font-weight: bold;
            letter-spacing: 2px;
            color: var(--primary-color);
        }

        .nav-links {
            display: flex;
            gap: 30px;
        }

        .nav-links a {
            font-size: 15px;
            font-weight: 500;
            color: var(--text-color);
        }

        .nav-links a:hover {
            color: var(--accent-color);
        }

        .nav-icons span {
            margin-left: 20px;
            cursor: pointer;
        }

        /* Hero Section */
        .hero {
            height: 500px;
            background-color: #f0f0f0;
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            position: relative;
            overflow: hidden;
        }

        .hero img {
            position: absolute;
            width: 100%;
            height: 100%;
            object-fit: cover;
            opacity: 0.8;
        }

        .hero-content {
            position: relative;
            z-index: 2;
            color: #fff;
            max-width: 600px;
        }

        .hero h1 {
            font-size: 48px;
            margin-bottom: 20px;
            font-weight: 300;
        }

        .hero p {
            font-size: 18px;
            margin-bottom: 30px;
        }

        /* Categories */
        .section-title {
            text-align: center;
            font-size: 28px;
            margin: 60px 0 40px;
            font-weight: 400;
            position: relative;
        }

        .section-title::after {
            content: '';
            display: block;
            width: 40px;
            height: 2px;
            background-color: var(--accent-color);
            margin: 15px auto 0;
        }

        .category-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 20px;
        }

        .category-card {
            position: relative;
            height: 300px;
            cursor: pointer;
        }

        .category-card img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .category-overlay {
            position: absolute;
            inset: 0;
            background: rgba(0, 0, 0, 0.2);
            display: flex;
            align-items: center;
            justify-content: center;
            transition: background 0.3s;
        }

        .category-card:hover .category-overlay {
            background: rgba(0, 0, 0, 0.1);
        }

        .category-name {
            color: #fff;
            font-size: 24px;
            border: 1px solid #fff;
            padding: 8px 20px;
        }

        /* Featured Products */
        .featured-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 30px;
        }

        .product-card {
            cursor: pointer;
        }

        .product-image {
            width: 100%;
            aspect-ratio: 3/4;
            background-color: #eee;
            margin-bottom: 15px;
            position: relative;
            overflow: hidden;
        }

        .product-image img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s;
        }

        .product-card:hover .product-image img {
            transform: scale(1.05);
        }

        .product-info h3 {
            font-size: 14px;
            font-weight: 500;
            margin-bottom: 5px;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .product-info .price {
            font-size: 14px;
            color: var(--gray-text);
        }

        /* Footer */
        footer {
            background-color: #111;
            color: #999;
            padding: 60px 0 30px;
            margin-top: 60px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: 2fr 1fr 1fr 1fr;
            gap: 40px;
            margin-bottom: 40px;
        }

        .footer-logo {
            color: #fff;
            font-size: 20px;
            margin-bottom: 20px;
        }

        .footer-col h4 {
            color: #fff;
            margin-bottom: 20px;
            font-size: 16px;
        }

        .footer-col ul li {
            margin-bottom: 10px;
        }

        .footer-col ul li a:hover {
            color: #fff;
        }

        .copyright {
            text-align: center;
            border-top: 1px solid #333;
            padding-top: 30px;
            font-size: 12px;
        }

        /* Responsive */
        @media (max-width: 768px) {
            .nav-links {
                display: none;
            }
            .hero h1 {
                font-size: 32px;
            }
            .category-grid, .featured-grid {
                grid-template-columns: 1fr;
            }
            .footer-grid {
                grid-template-columns: 1fr;
            }
        }
    </style>
</head>
